      SUBROUTINE R2TORSCC     TRANSFERS MATRIX R2 TO RSCC ----------------------------------------------------------------------      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'ELM17A.CIN'      INCLUDE 'RC2.CIN'      INCLUDE 'RS.CIN'      INCLUDE 'TC2.CIN'      INCLUDE 'TS.CIN'      INCLUDE 'UC2.CIN'      INCLUDE 'US.CIN'CC     LOCAL VARIABLESC      INTEGER         JK, JKM, JKLMC-----------------------------------------------------------------------C      DO 10 JK = 1, 36   10 RSL(JK) = RC2L(JK)      IF (NORD2 .GE. 2) THEN        DO 20 JKM = 1, 105   20   TSL(JKM) = TC2L(JKM)      ENDIF      IF (NORD2 .GE. 3) THEN        DO 30 JKLM = 1, 280   30   USL(JKLM) = UC2L(JKLM)      ENDIF      RETURN      END